import json, os, pathlib, subprocess, sys, tempfile, uuid
OBSERVER = 'package main

import (
 "bytes"
 "context"
 "crypto/sha256"
 "encoding/json"
 "errors"
 "fmt"
 "io/fs"
 "os"
 "path/filepath"
 "strings"
 "testing"
)

func TestABFrozenObservation(t *testing.T) {
 scope := os.Getenv("AB_SCOPE")
 output := map[string]any{}
 fixture := func(expression string) (*manager, string) {
  m := newTestManager(t)
  project := t.TempDir()
  writeFile(t, filepath.Join(m.paths.userSkills,"example","SKILL.md"), skillFile("example","Example skill.","body\n"))
  writeExecutable(t, filepath.Join(m.paths.userSkills,"example","check.sh"),"#!/bin/sh\nprintf checked\n")
  if err := saveLock(project,testLock(nil,map[string]string{"example":expression},nil)); err != nil { t.Fatal(err) }
  return m,project
 }
 get := func(m *manager,p string) (string,error) { var b bytes.Buffer; e:=m.getContext(context.Background(),p,"example","",&b); return b.String(),e }
 poison := func(p string) { if e:=os.MkdirAll(filepath.Join(p,"unrelated",".gitignore"),0755); e!=nil { t.Fatal(e) } }
 errClass := func(e error) string { if e==nil { return "ok" }; if errors.Is(e,context.Canceled) { return "canceled" }; if strings.Contains(e.Error(),"not enabled") { return "disabled" }; if strings.Contains(e.Error(),"read project ignore file") { return "traversal" }; return "other" }
 switch scope {
 case "existing":
  m,p:=fixture("true")
  body,e:=get(m,p); output["get"]=body; output["get_status"]=errClass(e)
  c,e:=m.scriptCommandContext(context.Background(),p,"example/check.sh",nil)
  if e!=nil { output["run_status"]=errClass(e) } else { b,e:=c.Output(); output["run"]=string(b);output["run_status"]=errClass(e) }
  var lines bytes.Buffer; e=m.getContext(context.Background(),p,"example","1:1",&lines); output["range"]=lines.String();output["range_status"]=errClass(e)
  if e:=saveLock(p,testLock(nil,map[string]string{"example":"lang rust"},nil));e!=nil {t.Fatal(e)}
  _,e=get(m,p);output["missing"]=errClass(e)
  writeFile(t,filepath.Join(p,"nested","src","lib.rs"),"")
  body,e=get(m,p);output["nested"]=body;output["nested_status"]=errClass(e)
  var list bytes.Buffer;e=m.listContext(context.Background(),p,&list);output["listed"]=strings.Contains(list.String(),`name="example"`);output["list_status"]=errClass(e)
 case "fast":
  rows:=[]any{}
  for _,pair:=range [][2]string{{"lang rust","Cargo.toml"},{"lang ts","main.ts"},{"tooling shadowtree",".shadowtree.toml"},{"tooling k8s","Chart.yaml"}} {
   m,p:=fixture(pair[0]);writeFile(t,filepath.Join(p,pair[1]),"");poison(p)
   body,e:=get(m,p);row:=map[string]any{"expression":pair[0],"body":body,"get":errClass(e)}
   c,e:=m.scriptCommandContext(context.Background(),p,"example/check.sh",nil);row["run"]=errClass(e)
   if e==nil { b,e:=c.Output();row["script"]=string(b);row["run"]=errClass(e) } else {row["script"]=""}
   rows=append(rows,row)
  };output["queries"]=rows
 case "semantics":
  rows:=[]any{}
  for _,expr:=range []string{"lang rust && true",`query=lang; "$query" rust`,"UNUSED=1 lang rust","lang rust >/dev/null",`lang rust >"$(lang rust; printf /dev/null)"`,"lang r*","tooling shadow*","has_dependency example"} {
   m,p:=fixture(expr)
   writeFile(t,filepath.Join(p,"Cargo.toml"),"[dependencies]\nexample = \"1\"\n")
   for _,name:=range []string{"rust",".shadowtree.toml","shadowtree"} {writeFile(t,filepath.Join(p,name),"")}
   body,e:=get(m,p);row:=map[string]any{"expression":expr,"clean":errClass(e),"body":body}
   poison(p);_,e=get(m,p);row["poisoned"]=errClass(e);rows=append(rows,row)
  };output["expressions"]=rows
 case "shared":
  m,p:=fixture("lang rust")
  writeFile(t,filepath.Join(p,".gitignore"),"ignored/\n");writeFile(t,filepath.Join(p,"ignored","Cargo.toml"),"")
  _,e:=get(m,p);output["ignored"]=errClass(e)
  nested:=filepath.Join(p,"src","nested","lib.rs");writeFile(t,nested,"");body,e:=get(m,p);output["added"]=body;output["added_status"]=errClass(e)
  if e:=os.Remove(nested);e!=nil {t.Fatal(e)};_,e=get(m,p);output["removed"]=errClass(e)
  writeFile(t,nested,"");ctx,cancel:=context.WithCancel(context.Background());cancel();var b bytes.Buffer;e=m.getContext(ctx,p,"example","",&b);output["canceled_get"]=errors.Is(e,context.Canceled)
  _,e=m.scriptCommandContext(ctx,p,"example/check.sh",nil);output["canceled_run"]=errors.Is(e,context.Canceled)
  writeFile(t,filepath.Join(m.paths.userSkills,"second","SKILL.md"),skillFile("second","Second skill.","second\n"))
  writeFile(t,filepath.Join(p,"other","main.py"),"")
  if e:=saveLock(p,testLock(nil,map[string]string{"example":"lang rust","second":"lang python"},nil));e!=nil {t.Fatal(e)}
  b.Reset();e=m.listContext(context.Background(),p,&b);output["list_status"]=errClass(e);output["rust_listed"]=strings.Contains(b.String(),`name="example"`);output["python_listed"]=strings.Contains(b.String(),`name="second"`)
  poison(p);b.Reset();e=m.listContext(context.Background(),p,&b);output["poisoned_list"]=errClass(e)
 case "cache":
  m,p:=fixture("lang rust");writeFile(t,filepath.Join(p,"Cargo.toml"),"")
  roots:=[]string{p,filepath.Dir(filepath.Dir(m.paths.managerHome))}
  snapshot:=func() map[string]string { result:=map[string]string{};for _,root:=range roots {e:=filepath.WalkDir(root,func(path string,d fs.DirEntry,e error) error {if e!=nil{return e};if d.Type().IsRegular(){b,e:=os.ReadFile(path);if e!=nil{return e};info,e:=d.Info();if e!=nil{return e};result[path]=fmt.Sprintf("%o:%x",info.Mode().Perm(),sha256.Sum256(b))};return nil});if e!=nil{t.Fatal(e)}};return result }
  before,_:=json.Marshal(snapshot());body,e:=get(m,p);output["body"]=body;output["get_status"]=errClass(e);body,e=get(m,p);output["repeat"]=body;output["repeat_status"]=errClass(e);after,_:=json.Marshal(snapshot());output["unchanged"]=bytes.Equal(before,after)
  if e:=os.Remove(filepath.Join(p,"Cargo.toml"));e!=nil{t.Fatal(e)};_,e=get(m,p);output["removed"]=errClass(e)
 default:t.Fatalf("unknown observer scope %q",scope)
 }
 b,e:=json.Marshal(output);if e!=nil{t.Fatal(e)};if e:=os.WriteFile(os.Getenv("AB_OUTPUT"),b,0600);e!=nil{t.Fatal(e)}
}
'
scope = sys.argv[1]
with tempfile.TemporaryDirectory(prefix='ab-observer-') as temp:
    private = pathlib.Path(temp)
    source = private / 'observer_test.go'
    source.write_text(OBSERVER)
    virtual = pathlib.Path.cwd() / ('ab_frozen_' + uuid.uuid4().hex + '_test.go')
    while virtual.exists() or virtual.is_symlink():
        virtual = pathlib.Path.cwd() / ('ab_frozen_' + uuid.uuid4().hex + '_test.go')
    overlay = private / 'overlay.json'
    overlay.write_text(json.dumps({'Replace': {str(virtual): str(source)}}))
    binary = private / 'observer'
    result = subprocess.run(['go', 'test', '-overlay=' + str(overlay), '-c', '-o', str(binary), '.'], capture_output=True, text=True)
    if result.returncode:
        sys.stderr.write(result.stdout + result.stderr)
        raise SystemExit(result.returncode)
    output = private / 'observed.json'
    env = dict(os.environ, AB_SCOPE=scope, AB_OUTPUT=str(output))
    result = subprocess.run([str(binary), '-test.run=^TestABFrozenObservation$', '-test.timeout=40s'], env=env, capture_output=True, text=True)
    if result.returncode:
        sys.stderr.write(result.stdout + result.stderr)
        raise SystemExit(result.returncode)
    print(json.dumps(json.loads(output.read_text()), sort_keys=True))

